        $replace = $sep === '_' ? '-' : '_';
        foreach ($attributes as &$attr) {
            $group = str_replace($sep, $replace, Tools::str2url((string) $attr['group']));
            $name = str_replace($sep, $replace, Tools::str2url((string) $attr['name']));
